import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { FiArrowRight, FiCheckCircle, FiClock, FiGrid, FiLogOut, FiUser, FiHome } from 'react-icons/fi';
import BrandMark from '../components/common/BrandMark';
import ErrorMessage from '../components/common/ErrorMessage';
import LoadingSpinner from '../components/common/LoadingSpinner';
import { useAuth } from '../hooks/useAuth';
import { getClientProfile } from '../services/siteService';

const ClientProfile = () => {
  const [profile, setProfile] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  const load = async () => {
    setLoading(true);
    try {
      const data = await getClientProfile();
      setProfile(data);
      setError('');
    } catch (err) {
      setError(err.response?.data?.error || 'Unable to load your client workspace.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, []);

  if (loading) return (
    <div className="portal-page grid place-items-center">
      <LoadingSpinner message="Preparing your workspace…" />
    </div>
  );

  if (error) return (
    <div className="portal-page grid place-items-center">
      <ErrorMessage message={error} onRetry={load} />
    </div>
  );

  const client = profile?.client;
  const stats = profile?.stats;

  return (
    <div className="portal-page">
      <div className="portal-shell profile-shell">
        {/* ============================================
            SIDEBAR - Professional Layout
            ============================================ */}
        <aside className="portal-sidebar">
          {/* Top: Aeroview 360 Brand */}
          <div className="sidebar-brand">
            <BrandMark />
            <div className="sidebar-brand__text">
              <span className="text-xs font-bold text-textLight uppercase tracking-wider">Aeroview 360</span>
              <span className="text-[10px] text-textMuted">Client Portal</span>
            </div>
          </div>

          <div className="portal-rule" />

          {/* Client Logo + Company Name */}
          <div className="sidebar-client">
            {client?.company_logo ? (
              <img
                src={client.company_logo}
                alt={client.client_name}
                className="sidebar-client__logo"
              />
            ) : (
              <div className="sidebar-client__avatar">
                {client?.client_name?.slice(0, 2).toUpperCase()}
              </div>
            )}
            <div className="sidebar-client__info">
              <strong>{client?.client_name}</strong>
              <span>Client Workspace</span>
            </div>
          </div>

          <div className="portal-rule" />

          {/* Navigation */}
          <nav className="sidebar-nav">
            <button
              onClick={() => navigate('/profile')}
              className="sidebar-nav__item active"
            >
              <FiHome />
              <span>Dashboard</span>
            </button>
            <button
              onClick={() => navigate('/sites')}
              className="sidebar-nav__item"
            >
              <FiGrid />
              <span>Project Sites</span>
            </button>
          </nav>

          <div className="portal-rule" />

          {/* User Info & Logout */}
          <div className="sidebar-user">
            <div className="sidebar-user__info">
              <span>Signed in as</span>
              <strong>{user?.name}</strong>
            </div>
            <button
              onClick={() => { logout(); navigate('/login'); }}
              className="sidebar-user__logout"
            >
              <FiLogOut />
              <span>Sign Out</span>
            </button>
          </div>
        </aside>

        {/* ============================================
            MAIN CONTENT
            ============================================ */}
        <main className="portal-main">
          {/* Header with Client Logo */}
          <header className="portal-header">
            <div className="portal-heading">
              <div className="portal-heading__avatar">
                {client?.company_logo ? (
                  <img
                    src={client.company_logo}
                    alt={client.client_name}
                    className="w-12 h-12 rounded-full object-cover border-2 border-primaryDark"
                  />
                ) : (
                  <FiUser className="text-2xl" />
                )}
              </div>
              <div>
                <h1 className="text-2xl font-bold text-textPrimary">
                  Welcome Back, {user?.name?.split(' ')[0]}!
                </h1>
                <p className="text-sm text-textSecondary">
                  {client?.client_name} • Client Dashboard
                </p>
              </div>
            </div>
          </header>

          {/* Content */}
          <div className="portal-content">
            <section className="profile-hero">
              <div>
                <span className="text-xs font-semibold text-primaryDark uppercase tracking-wider">
                  Client Dashboard
                </span>
                <h2 className="text-2xl font-bold text-textPrimary mt-1">
                  Everything about your project, in one clear view.
                </h2>
                <p className="text-textSecondary mt-2">
                  Select a site to access progress tours, videos, image folders, and final deliverables.
                </p>
                <button
                  onClick={() => navigate('/sites')}
                  className="mt-4 btn-primary inline-flex items-center gap-2"
                >
                  View Project Sites <FiArrowRight />
                </button>
              </div>
            </section>

            {/* Stats Cards */}
            <div className="portal-grid portal-grid--three">
              <div className="data-card stat-card">
                <span><FiGrid /></span>
                <strong>{stats?.active_sites || 0}</strong>
                <small>Active Sites</small>
              </div>
              <div className="data-card stat-card">
                <span><FiCheckCircle /></span>
                <strong>{stats?.completed_sites || 0}</strong>
                <small>Completed Sites</small>
              </div>
              <div className="data-card stat-card">
                <span><FiClock /></span>
                <strong>{stats?.latest_update || 'N/A'}</strong>
                <small>Latest Update</small>
              </div>
            </div>

            <div className="info-bar">
              <FiCheckCircle />
              Your account only displays sites and project content assigned to {client?.client_name}.
            </div>
          </div>
        </main>
      </div>
    </div>
  );
};

export default ClientProfile;
